import sympy as sp; x, y = sp.symbols('x y', real=True); parabola_eq = y**2 - (4*x + 4*y + 4); circle_eq = (x + 1)**2 + (y - 2)**2 - 4; intersections = sp.solve([parabola_eq, circle_eq], [x, y]); sum_val = sum(coord for pt in intersections for coord in pt); all_satisfied = all(parabola_eq.subs({x: pt[0], y: pt[1]}) == 0 and circle_eq.subs({x: pt[0], y: pt[1]}) == 0 for pt in intersections); print('VERIFY_PASS' if all_satisfied and sum_val == 2 else 'VERIFY_FAIL')